WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pl_r_adjust'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '资源不足与调配', 'kp-pl-r-adjust', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "物资调配（货物集中问题）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "小往大处靠！运费最小化。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“公路边有五个仓库，分别存有 10, 20, 50, 30, 40 吨货物。现要将所有货物集中到一个仓库，运费与重量和距离成正比，集中到哪最省钱？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心战法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不要去算每一段的具体运费。把路分成两端，比较两端的总重量。哪边重，另一边的货物就必须往这边运！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[在草图上标出每个仓库的重量] --> B[从最边缘的仓库开始, 假设把它搬到相邻仓库]\nB --> C[比较移动这批货后, 左边总重量和右边总重量]\nC --> D[如果左边轻, 就继续往右边搬; 如果右边轻, 就往左边搬]\nD --> E[直到某一点, 无论往左还是往右, 目标方向的重量都更轻, 这个点就是终点]"}}]}$$ AS jsonb), NULL, '资源不足与调配的核心考点与实战推导。', category_node.id, CAST('["数量关系", "资源不足与调配"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pl_r_adjust", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
